class Solution {
    public int maxScore(int[] nums) {
        int m = nums.length;
        int[][] gcd = new int[m][m];

        for (int i = 0; i < m; i++) {
            for (int j = i + 1; j < m; j++) {
                int a = nums[i];
                int b = nums[j];
                while (b != 0) {
                    int remainder = a % b;
                    a = b;
                    b = remainder;
                }
                gcd[i][j] = a;
            }
        }

        int[] dp = new int[1 << m];

        for (int mask = 1; mask < dp.length; mask++) {
            int count = Integer.bitCount(mask);
            if ((count & 1) != 0) {
                continue;
            }

            int operation = count / 2;
            for (int i = 0; i < m; i++) {
                if ((mask & (1 << i)) == 0) {
                    continue;
                }

                for (int j = i + 1; j < m; j++) {
                    if ((mask & (1 << j)) == 0) {
                        continue;
                    }

                    int previous = mask ^ (1 << i) ^ (1 << j);
                    dp[mask] = Math.max(
                        dp[mask],
                        dp[previous] + operation * gcd[i][j]
                    );
                }
            }
        }

        return dp[dp.length - 1];
    }
}

